mapper.select:
${pagingTop} SELECT a.homepage_id, a.human_book_idx, b.human_apply_idx, a.human_book_title, a.activity_category, b.human_apply_place, b.human_return_date, b.human_apply_status, b.unapproved_reasons FROM human_book a, human_book_apply b WHERE a.homepage_id = b.homepage_id AND a.human_book_idx = b.human_book_idx AND b.homepage_id = #{homepage_id}
AND b.add_id = #{add_id}
AND ${search_type} LIKE '%' || #{search_text} || '%'
ORDER BY b.add_date DESC ${pagingBottom}

SELECT COUNT(*) FROM human_book a, human_book_apply b WHERE a.homepage_id = b.homepage_id AND a.human_book_idx = b.human_book_idx AND b.homepage_id = #{homepage_id}
AND b.add_id = #{add_id}
AND ${search_type} LIKE '%' || #{search_text} || '%'

