	HUMAN_BOOK_APPLY
SET
	human_apply_status = '2',
	human_return_date = SYSDATE
WHERE
	homepage_id = #{homepage_id}
AND	human_book_idx = #{human_book_idx}
AND	human_apply_idx = #{human_apply_idx}
AND	add_id = #{add_id}

